// Package notesapi implements a small in-memory REST API for notes.
package notesapi

import "net/http"

// Note is a single note. Do not change this type.
type Note struct {
	ID       string `json:"id"`
	Title    string `json:"title"`
	Body     string `json:"body"`
	Priority int    `json:"priority"`
	Done     bool   `json:"done"`
}

// Server serves the notes REST API. See spec.md for the required endpoints.
type Server struct{}

// NewServer returns a new, empty Server. Do not change this signature.
func NewServer() *Server {
	return &Server{}
}

func (s *Server) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusNotImplemented)
}

import 'dart:convert';

import 'package:http/http.dart' as http;

/// A single note. Mirrors the JSON shape returned by the Go notes API.
class Note {
  final String id;
  String title;
  String body;
  int priority;
  bool done;

  Note({
    required this.id,
    required this.title,
    this.body = '',
    this.priority = 3,
    this.done = false,
  });

  factory Note.fromJson(Map<String, dynamic> json) {
    throw UnimplementedError();
  }

  Map<String, dynamic> toJson() {
    throw UnimplementedError();
  }
}

/// Thrown by [NotesApiClient] when the server responds with a non-success
/// status code. Already defined — do not change.
class NotesApiException implements Exception {
  final int statusCode;
  final String message;
  NotesApiException(this.statusCode, this.message);

  @override
  String toString() => 'NotesApiException($statusCode, $message)';
}

/// Talks to the Go notes API server over HTTP. See spec.md for the exact
/// request/response contract for each method.
class NotesApiClient {
  NotesApiClient(this.baseUrl, {http.Client? httpClient})
      : httpClient = httpClient ?? http.Client();

  final String baseUrl;
  final http.Client httpClient;

  Future<Note> createNote({
    required String title,
    String body = '',
    int priority = 3,
  }) {
    throw UnimplementedError();
  }

  Future<List<Note>> listNotes() {
    throw UnimplementedError();
  }

  Future<Note> getNote(String id) {
    throw UnimplementedError();
  }

  Future<Note> updateNote(
    String id, {
    String? title,
    String? body,
    int? priority,
    bool? done,
  }) {
    throw UnimplementedError();
  }

  Future<void> deleteNote(String id) {
    throw UnimplementedError();
  }
}

import 'notes_client.dart';

/// In-memory view-model wrapping a [NotesApiClient] for a UI layer. See
/// spec.md for the exact behavior of each member.
class NotesViewModel {
  NotesViewModel(this.client);

  final NotesApiClient client;

  List<Note> get notes {
    throw UnimplementedError();
  }

  List<Note> get pending {
    throw UnimplementedError();
  }

  List<Note> get completed {
    throw UnimplementedError();
  }

  Future<void> load() {
    throw UnimplementedError();
  }

  Future<Note> addNote({
    required String title,
    String body = '',
    int priority = 3,
  }) {
    throw UnimplementedError();
  }

  Future<void> toggleDone(String id) {
    throw UnimplementedError();
  }

  Future<void> remove(String id) {
    throw UnimplementedError();
  }
}

