// Package notesapi implements a small in-memory REST API for notes.
package notesapi

import (
	"encoding/json"
	"net/http"
	"sort"
	"strconv"
	"strings"
	"sync"
)

// Note is a single note. Do not change this type.
type Note struct {
	ID       string `json:"id"`
	Title    string `json:"title"`
	Body     string `json:"body"`
	Priority int    `json:"priority"`
	Done     bool   `json:"done"`
}

// Server serves the notes REST API. See spec.md for the required endpoints.
type Server struct {
	mu       sync.Mutex
	notes    map[int]Note
	nextID   int
}

// NewServer returns a new, empty Server. Do not change this signature.
func NewServer() *Server {
	return &Server{notes: make(map[int]Note), nextID: 1}
}

func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	json.NewEncoder(w).Encode(v)
}

func writeError(w http.ResponseWriter, status int, msg string) {
	writeJSON(w, status, map[string]string{"error": msg})
}

func (s *Server) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	path := strings.TrimPrefix(r.URL.Path, "/")
	parts := strings.Split(path, "/")

	switch {
	case len(parts) == 1 && parts[0] == "notes":
		switch r.Method {
		case http.MethodPost:
			s.handleCreate(w, r)
		case http.MethodGet:
			s.handleList(w)
		default:
			writeError(w, http.StatusNotFound, "not found")
		}
	case len(parts) == 2 && parts[0] == "notes" && parts[1] != "":
		id, err := strconv.Atoi(parts[1])
		if err != nil {
			writeError(w, http.StatusNotFound, "not found")
			return
		}
		switch r.Method {
		case http.MethodGet:
			s.handleGet(w, id)
		case http.MethodPatch:
			s.handlePatch(w, r, id)
		case http.MethodDelete:
			s.handleDelete(w, id)
		default:
			writeError(w, http.StatusNotFound, "not found")
		}
	default:
		writeError(w, http.StatusNotFound, "not found")
	}
}

func (s *Server) handleCreate(w http.ResponseWriter, r *http.Request) {
	var payload struct {
		Title    string `json:"title"`
		Body     string `json:"body"`
		Priority *int   `json:"priority"`
	}
	if err := json.NewDecoder(r.Body).Decode(&payload); err != nil {
		writeError(w, http.StatusBadRequest, "invalid JSON body")
		return
	}
	if payload.Title == "" {
		writeError(w, http.StatusBadRequest, "title is required and must be non-empty")
		return
	}
	priority := 3
	if payload.Priority != nil {
		if *payload.Priority < 1 || *payload.Priority > 5 {
			writeError(w, http.StatusBadRequest, "priority must be an integer between 1 and 5")
			return
		}
		priority = *payload.Priority
	}

	s.mu.Lock()
	defer s.mu.Unlock()
	note := Note{
		ID:       strconv.Itoa(s.nextID),
		Title:    payload.Title,
		Body:     payload.Body,
		Priority: priority,
		Done:     false,
	}
	s.notes[s.nextID] = note
	s.nextID++
	writeJSON(w, http.StatusCreated, note)
}

func (s *Server) handleList(w http.ResponseWriter) {
	s.mu.Lock()
	notes := make([]Note, 0, len(s.notes))
	for _, n := range s.notes {
		notes = append(notes, n)
	}
	s.mu.Unlock()

	sort.SliceStable(notes, func(i, j int) bool {
		if notes[i].Priority != notes[j].Priority {
			return notes[i].Priority < notes[j].Priority
		}
		return atoi(notes[i].ID) < atoi(notes[j].ID)
	})
	writeJSON(w, http.StatusOK, notes)
}

func (s *Server) handleGet(w http.ResponseWriter, id int) {
	s.mu.Lock()
	note, ok := s.notes[id]
	s.mu.Unlock()
	if !ok {
		writeError(w, http.StatusNotFound, "note not found")
		return
	}
	writeJSON(w, http.StatusOK, note)
}

func (s *Server) handlePatch(w http.ResponseWriter, r *http.Request, id int) {
	var payload struct {
		Title    *string `json:"title"`
		Body     *string `json:"body"`
		Priority *int    `json:"priority"`
		Done     *bool   `json:"done"`
	}
	if err := json.NewDecoder(r.Body).Decode(&payload); err != nil {
		writeError(w, http.StatusBadRequest, "invalid JSON body")
		return
	}
	if payload.Title != nil && *payload.Title == "" {
		writeError(w, http.StatusBadRequest, "title must be non-empty")
		return
	}
	if payload.Priority != nil && (*payload.Priority < 1 || *payload.Priority > 5) {
		writeError(w, http.StatusBadRequest, "priority must be an integer between 1 and 5")
		return
	}

	s.mu.Lock()
	defer s.mu.Unlock()
	note, ok := s.notes[id]
	if !ok {
		writeError(w, http.StatusNotFound, "note not found")
		return
	}
	if payload.Title != nil {
		note.Title = *payload.Title
	}
	if payload.Body != nil {
		note.Body = *payload.Body
	}
	if payload.Priority != nil {
		note.Priority = *payload.Priority
	}
	if payload.Done != nil {
		note.Done = *payload.Done
	}
	s.notes[id] = note
	writeJSON(w, http.StatusOK, note)
}

func (s *Server) handleDelete(w http.ResponseWriter, id int) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, ok := s.notes[id]; !ok {
		writeError(w, http.StatusNotFound, "note not found")
		return
	}
	delete(s.notes, id)
	w.WriteHeader(http.StatusNoContent)
}

func atoi(s string) int {
	n, _ := strconv.Atoi(s)
	return n
}

package notesapi

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"reflect"
	"sort"
	"strings"
	"sync"
	"testing"
)

func doReq(t *testing.T, s http.Handler, method, path, body string) *httptest.ResponseRecorder {
	t.Helper()
	var reader io.Reader
	if body != "" {
		reader = strings.NewReader(body)
	}
	req := httptest.NewRequest(method, path, reader)
	rec := httptest.NewRecorder()
	s.ServeHTTP(rec, req)
	return rec
}

func TestSmoke(t *testing.T) {
	s := NewServer()

	// Empty list returns [] not null.
	rec := doReq(t, s, "GET", "/notes", "")
	if rec.Code != 200 || !bytes.Equal(bytes.TrimSpace(rec.Body.Bytes()), []byte("[]")) {
		t.Fatalf("empty list: got %d %q", rec.Code, rec.Body.String())
	}

	// Create with defaults.
	rec = doReq(t, s, "POST", "/notes", `{"title":"a"}`)
	if rec.Code != 201 {
		t.Fatalf("create: got %d %q", rec.Code, rec.Body.String())
	}
	var n1 Note
	if err := json.Unmarshal(rec.Body.Bytes(), &n1); err != nil {
		t.Fatal(err)
	}
	want1 := Note{ID: "1", Title: "a", Body: "", Priority: 3, Done: false}
	if n1 != want1 {
		t.Fatalf("n1 = %+v, want %+v", n1, want1)
	}

	// Create with priority 1.
	rec = doReq(t, s, "POST", "/notes", `{"title":"b","body":"bb","priority":1}`)
	if rec.Code != 201 {
		t.Fatalf("create2: got %d %q", rec.Code, rec.Body.String())
	}

	// Create with priority 5.
	rec = doReq(t, s, "POST", "/notes", `{"title":"c","priority":5}`)
	if rec.Code != 201 {
		t.Fatalf("create3: got %d %q", rec.Code, rec.Body.String())
	}

	// Invalid inputs.
	for _, body := range []string{`{`, `{"title":""}`, `{"title":"x","priority":0}`, `{"title":"x","priority":6}`, `{"title":"x","priority":2.5}`, `{"title":5}`} {
		rec = doReq(t, s, "POST", "/notes", body)
		if rec.Code != 400 {
			t.Fatalf("POST %q: got %d, want 400", body, rec.Code)
		}
		var errResp map[string]string
		if err := json.Unmarshal(rec.Body.Bytes(), &errResp); err != nil || errResp["error"] == "" {
			t.Fatalf("POST %q: bad error body %q", body, rec.Body.String())
		}
	}

	// List ordering: priority asc, then id asc.
	rec = doReq(t, s, "GET", "/notes", "")
	var list []Note
	if err := json.Unmarshal(rec.Body.Bytes(), &list); err != nil {
		t.Fatal(err)
	}
	wantIDs := []string{"2", "1", "3"}
	var gotIDs []string
	for _, n := range list {
		gotIDs = append(gotIDs, n.ID)
	}
	if !reflect.DeepEqual(gotIDs, wantIDs) {
		t.Fatalf("list order = %v, want %v", gotIDs, wantIDs)
	}

	// Get existing / missing.
	rec = doReq(t, s, "GET", "/notes/2", "")
	if rec.Code != 200 {
		t.Fatalf("get: got %d", rec.Code)
	}
	rec = doReq(t, s, "GET", "/notes/99", "")
	if rec.Code != 404 {
		t.Fatalf("get missing: got %d", rec.Code)
	}

	// Patch partial.
	rec = doReq(t, s, "PATCH", "/notes/2", `{"done":true}`)
	if rec.Code != 200 {
		t.Fatalf("patch: got %d %q", rec.Code, rec.Body.String())
	}
	var patched Note
	if err := json.Unmarshal(rec.Body.Bytes(), &patched); err != nil {
		t.Fatal(err)
	}
	if !patched.Done || patched.Title != "b" || patched.Body != "bb" || patched.Priority != 1 {
		t.Fatalf("patched = %+v", patched)
	}

	// Patch invalid.
	for _, body := range []string{`{`, `{"title":""}`, `{"priority":9}`} {
		rec = doReq(t, s, "PATCH", "/notes/2", body)
		if rec.Code != 400 {
			t.Fatalf("PATCH %q: got %d, want 400", body, rec.Code)
		}
	}
	rec = doReq(t, s, "PATCH", "/notes/99", `{"done":true}`)
	if rec.Code != 404 {
		t.Fatalf("patch missing: got %d", rec.Code)
	}

	// Delete.
	rec = doReq(t, s, "DELETE", "/notes/1", "")
	if rec.Code != 204 {
		t.Fatalf("delete: got %d", rec.Code)
	}
	rec = doReq(t, s, "DELETE", "/notes/1", "")
	if rec.Code != 404 {
		t.Fatalf("delete missing: got %d", rec.Code)
	}

	// Unknown routes.
	for _, req := range []struct{ method, path string }{
		{"GET", "/"}, {"GET", "/nope"}, {"PUT", "/notes"}, {"POST", "/notes/1"},
		{"GET", "/notes/abc"}, {"HEAD", "/notes/1"},
	} {
		rec = doReq(t, s, req.method, req.path, "")
		if rec.Code != 404 {
			t.Fatalf("%s %s: got %d, want 404", req.method, req.path, rec.Code)
		}
	}
}

func TestConcurrentIDs(t *testing.T) {
	s := NewServer()
	var wg sync.WaitGroup
	const n = 50
	for i := 0; i < n; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			rec := doReq(t, s, "POST", "/notes", `{"title":"x"}`)
			if rec.Code != 201 {
				t.Errorf("create: got %d", rec.Code)
			}
		}()
	}
	wg.Wait()
	rec := doReq(t, s, "GET", "/notes", "")
	var list []Note
	if err := json.Unmarshal(rec.Body.Bytes(), &list); err != nil {
		t.Fatal(err)
	}
	if len(list) != n {
		t.Fatalf("got %d notes, want %d", len(list), n)
	}
	seen := map[string]bool{}
	for _, note := range list {
		if seen[note.ID] {
			t.Fatalf("duplicate id %s", note.ID)
		}
		seen[note.ID] = true
	}
	for i := 1; i <= n; i++ {
		if !seen[fmt.Sprint(i)] {
			t.Fatalf("missing id %d", i)
		}
	}
	// Sort order check on concurrent list.
	sorted := make([]Note, len(list))
	copy(sorted, list)
	sort.SliceStable(sorted, func(i, j int) bool { return sorted[i].Priority < sorted[j].Priority })
	if !reflect.DeepEqual(list, sorted) {
		t.Fatal("list not sorted by priority")
	}
}

import 'dart:convert';

import 'package:http/http.dart' as http;

/// A single note. Mirrors the JSON shape returned by the Go notes API.
class Note {
  final String id;
  String title;
  String body;
  int priority;
  bool done;

  Note({
    required this.id,
    required this.title,
    this.body = '',
    this.priority = 3,
    this.done = false,
  });

  factory Note.fromJson(Map<String, dynamic> json) {
    return Note(
      id: json['id'] as String,
      title: json['title'] as String,
      body: (json['body'] as String?) ?? '',
      priority: (json['priority'] as num?)?.toInt() ?? 3,
      done: (json['done'] as bool?) ?? false,
    );
  }

  Map<String, dynamic> toJson() {
    return {
      'id': id,
      'title': title,
      'body': body,
      'priority': priority,
      'done': done,
    };
  }
}

/// Thrown by [NotesApiClient] when the server responds with a non-success
/// status code. Already defined — do not change.
class NotesApiException implements Exception {
  final int statusCode;
  final String message;
  NotesApiException(this.statusCode, this.message);

  @override
  String toString() => 'NotesApiException($statusCode, $message)';
}

/// Talks to the Go notes API server over HTTP. See spec.md for the exact
/// request/response contract for each method.
class NotesApiClient {
  NotesApiClient(this.baseUrl, {http.Client? httpClient})
      : httpClient = httpClient ?? http.Client();

  final String baseUrl;
  final http.Client httpClient;

  String _errorMessage(http.Response response) {
    final dynamic decoded = jsonDecode(response.body);
    if (decoded is Map<String, dynamic> && decoded['error'] is String) {
      return decoded['error'] as String;
    }
    return response.body;
  }

  Future<Note> createNote({
    required String title,
    String body = '',
    int priority = 3,
  }) async {
    final response = await httpClient.post(
      '$baseUrl/notes',
      headers: {'Content-Type': 'application/json'},
      body: jsonEncode({'title': title, 'body': body, 'priority': priority}),
    );
    if (response.statusCode != 201) {
      throw NotesApiException(response.statusCode, _errorMessage(response));
    }
    return Note.fromJson(jsonDecode(response.body) as Map<String, dynamic>);
  }

  Future<List<Note>> listNotes() async {
    final response = await httpClient.get('$baseUrl/notes');
    if (response.statusCode != 200) {
      throw NotesApiException(response.statusCode, _errorMessage(response));
    }
    final dynamic decoded = jsonDecode(response.body);
    return (decoded as List).map(Note.fromJson).toList();
  }

  Future<Note> getNote(String id) async {
    final response = await httpClient.get('$baseUrl/notes/$id');
    if (response.statusCode != 200) {
      throw NotesApiException(response.statusCode, _errorMessage(response));
    }
    return Note.fromJson(jsonDecode(response.body) as Map<String, dynamic>);
  }

  Future<Note> updateNote(
    String id, {
    String? title,
    String? body,
    int? priority,
    bool? done,
  }) async {
    final payload = <String, dynamic>{};
    if (title != null) payload['title'] = title;
    if (body != null) payload['body'] = body;
    if (priority != null) payload['priority'] = priority;
    if (done != null) payload['done'] = done;
    final response = await httpClient.patch(
      '$baseUrl/notes/$id',
      headers: {'Content-Type': 'application/json'},
      body: jsonEncode(payload),
    );
    if (response.statusCode != 200) {
      throw NotesApiException(response.statusCode, _errorMessage(response));
    }
    return Note.fromJson(jsonDecode(response.body) as Map<String, dynamic>);
  }

  Future<void> deleteNote(String id) async {
    final response = await httpClient.delete('$baseUrl/notes/$id');
    if (response.statusCode != 204) {
      throw NotesApiException(response.statusCode, _errorMessage(response));
    }
  }
}

import 'notes_client.dart';

/// In-memory view-model wrapping a [NotesApiClient] for a UI layer. See
/// spec.md for the exact behavior of each member.
class NotesViewModel {
  NotesViewModel(this.client);

  final NotesApiClient client;

  final List<Note> _notes = [];

  List<Note> get notes {
    final sorted = List<Note>.of(_notes);
    sorted.sort((a, b) => a.priority.compareTo(b.priority));
    return List.unmodifiable(sorted);
  }

  List<Note> get pending => notes.where((n) => !n.done).toList();

  List<Note> get completed => notes.where((n) => n.done).toList();

  Future<void> load() async {
    _notes
      ..clear()
      ..addAll(await client.listNotes());
  }

  Future<Note> addNote({
    required String title,
    String body = '',
    int priority = 3,
  }) async {
    final note = await client.createNote(
      title: title,
      body: body,
      priority: priority,
    );
    _notes.add(note);
    return note;
  }

  Future<void> toggleDone(String id) async {
    final index = _notes.indexWhere((n) => n.id == id);
    if (index == -1) {
      throw ArgumentError('no note with id $id');
    }
    final current = _notes[index];
    final updated = await client.updateNote(id, done: !current.done);
    _notes[index] = updated;
  }

  Future<void> remove(String id) async {
    final index = _notes.indexWhere((n) => n.id == id);
    if (index == -1) {
      throw ArgumentError('no note with id $id');
    }
    await client.deleteNote(id);
    _notes.removeAt(index);
  }
}

